var t=`0021-kholodets`;var n=`world-0021`;var o=`UA`;var a=`eastern-europe`;var s=4;var r=528;var l={en:`Kholodets`,ua:`Холодець`};var g={en:`A classic dish from Ukraine, featuring pork hock, beef shank, yellow onion, carrot. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Україна. Основні складники: свиняча рулька, яловича гомілка, жовта цибуля, морква. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 150 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 150 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:150,i:[[`pork-hock`,600,`g`],[`beef-shank`,500,`g`],[`water`,2200,`ml`],[`yellow-onion`,120,`g`],[`carrot`,130,`g`],[`bay-leaf`,2,`leaf`],[`allspice-berries`,4,`pcs`]]},{en:`Shred or tear the cooked components, then fold together with the listed additions.`,ua:`Нашаткуйте або розберіть готові компоненти на волокна й змішайте з зазначеними додатками.`,t:[`shredding`,`mixing`],m:15,i:[[`garlic`,5,`clove`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Dissolve or bloom the setting ingredients as directed, combine with the base and refrigerate for about 360 minutes until fully set.`,ua:`Підготуйте желювальні складники за інструкцією, змішайте з основою та охолоджуйте приблизно 360 хвилин до повного застигання.`,t:[`gelatin-setting`,`rapid-chilling`],m:360,i:[[`gelatin-powder`,12,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`horseradish-root`,35,`g`]]}];var h={slug:t,id:n,country:`UA`,region:a,servings:4,minutes:528,title:l,text:g,steps:d};export{o as country,h as default,n as id,r as minutes,a as region,s as servings,t as slug,d as steps,g as text,l as title};